-- INSERT INTO `broadcast_text` (`ID`, `Text`, `Text1`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `VoiceOverPriorityID`, `SoundKitID1`, `SoundKitID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`) VALUES (223199, 'The Artisan''s Consortium is a collection of entrepreneurs and artisans, much like yourself, who provide goods and services to crafters and gatherers in need.
-- 
-- As we speak, the Artisan''s Consortium is setting up a trading service to connect crafters with their customers!
-- 
-- Do you know any artisans who might want to know about our work?', 'The Artisan''s Consortium is a collection of entrepreneurs and artisans, much like yourself, who provide goods and services to crafters and gatherers in need.
-- 
-- As we speak, the Artisan''s Consortium is setting up a trading service to connect crafters with their customers!
-- 
-- Do you know any artisans who might want to know about our work?', 0, 0, 0, 0, 0, 4, 0, 0, 1, 0, 0, 0, 0, 0) ON DUPLICATE KEY UPDATE `ID`=VALUES(`ID`), `Text`=VALUES(`Text`), `Text1`=VALUES(`Text1`), `LanguageID`=VALUES(`LanguageID`), `ConditionID`=VALUES(`ConditionID`), `EmotesID`=VALUES(`EmotesID`), `Flags`=VALUES(`Flags`), `ChatBubbleDurationMs`=VALUES(`ChatBubbleDurationMs`), `VoiceOverPriorityID`=VALUES(`VoiceOverPriorityID`), `SoundKitID1`=VALUES(`SoundKitID1`), `SoundKitID2`=VALUES(`SoundKitID2`), `EmoteID1`=VALUES(`EmoteID1`), `EmoteID2`=VALUES(`EmoteID2`), `EmoteID3`=VALUES(`EmoteID3`), `EmoteDelay1`=VALUES(`EmoteDelay1`), `EmoteDelay2`=VALUES(`EmoteDelay2`), `EmoteDelay3`=VALUES(`EmoteDelay3`);
