-- INSERT INTO `broadcast_text` (`ID`, `Text`, `Text1`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `VoiceOverPriorityID`, `SoundKitID1`, `SoundKitID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`) VALUES (223309, '', 'Oh! That is a lovely question, thank you for asking. For years as a crafter, I tried to peddle my goods, but it was so hard to find clients. I found myself just wandering the city shouting if anyone needed something made.
-- 
-- The Artisan''s Consortium offers something better: a new way of connecting clients and crafters. They are not just a business, they are an innovation on the market!
-- 
-- But what about you? Why do you hone your trade?', 0, 0, 0, 0, 0, 4, 0, 0, 0, 0, 0, 0, 0, 0) ON DUPLICATE KEY UPDATE `ID`=VALUES(`ID`), `Text`=VALUES(`Text`), `Text1`=VALUES(`Text1`), `LanguageID`=VALUES(`LanguageID`), `ConditionID`=VALUES(`ConditionID`), `EmotesID`=VALUES(`EmotesID`), `Flags`=VALUES(`Flags`), `ChatBubbleDurationMs`=VALUES(`ChatBubbleDurationMs`), `VoiceOverPriorityID`=VALUES(`VoiceOverPriorityID`), `SoundKitID1`=VALUES(`SoundKitID1`), `SoundKitID2`=VALUES(`SoundKitID2`), `EmoteID1`=VALUES(`EmoteID1`), `EmoteID2`=VALUES(`EmoteID2`), `EmoteID3`=VALUES(`EmoteID3`), `EmoteDelay1`=VALUES(`EmoteDelay1`), `EmoteDelay2`=VALUES(`EmoteDelay2`), `EmoteDelay3`=VALUES(`EmoteDelay3`);
