-- Just the thought of what lies ahead gets me excited!', '', 0, 0, 0, 0, 0, 4, 0, 0, 0, 0, 0, 0, 0, 0) ON DUPLICATE KEY UPDATE `ID`=VALUES(`ID`), `Text`=VALUES(`Text`), `Text1`=VALUES(`Text1`), `LanguageID`=VALUES(`LanguageID`), `ConditionID`=VALUES(`ConditionID`), `EmotesID`=VALUES(`EmotesID`), `Flags`=VALUES(`Flags`), `ChatBubbleDurationMs`=VALUES(`ChatBubbleDurationMs`), `VoiceOverPriorityID`=VALUES(`VoiceOverPriorityID`), `SoundKitID1`=VALUES(`SoundKitID1`), `SoundKitID2`=VALUES(`SoundKitID2`), `EmoteID1`=VALUES(`EmoteID1`), `EmoteID2`=VALUES(`EmoteID2`), `EmoteID3`=VALUES(`EmoteID3`), `EmoteDelay1`=VALUES(`EmoteDelay1`), `EmoteDelay2`=VALUES(`EmoteDelay2`), `EmoteDelay3`=VALUES(`EmoteDelay3`);
